import json,csv,html,hashlib
from pathlib import Path
from decimal import Decimal
from collections import Counter
P=Path(__file__).parent
e=json.loads((P/'evidence.json').read_text()); rows=[r for p in e['settlementPages'] for r in p['data']['items']]
assert len(rows)==12066 and len({r['id'] for r in rows})==12066 and len(e['settlementPages'])==242
sku=e['skuAnalysis']; products=[x for x in sku if x['sales']>0]; assert len(products)==71
assert sum(x['sales'] for x in sku)==4215915 and sum(x['refund'] for x in sku)==-189658
assert sum(x['net']-x['tax'] for x in sku)==2031158
H=lambda x:html.escape(str(x)); M=lambda x:f'{Decimal(x)/100:,.2f}'; Q=lambda x:f'{x*100:.1f}%'
mp={x['sellerSku']:x['asin'] for x in e['listings']['data']['items']}
high=sorted([x for x in products if -(x['commission']+x['fba'])/x['sales']>=.5],key=lambda x:-(x['commission']+x['fba'])/x['sales'],reverse=True)
assert len(high)==13
age=e['ageAnalysis']; aged=sorted([x for x in age if (x['a181'] or 0)+(x['a271'] or 0)>0],key=lambda x:(x['a271'] or 0,x['a181'] or 0),reverse=True)
ret=e['returns']['data']['items']; reasons=Counter(x['reason']['code'] for x in ret); counts=Counter(x['sellerSku'] for x in ret)
def table(head,body):
 return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+H(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in r)+'</tr>' for r in body)+'</tbody></table></div>'
