def sec(t,c):s.append('<section><h2>'+t+'</h2>'+c+'</section>')
header='''<header><p>粒粒 MCP · aoocy-us · 美国站 · 2026-11-09</p><h1>利润体检 · 数据受限分析稿</h1><p>近 30 天目标窗口为 2026-10-10 至 2026-11-08，已读取 12,066 行实际结算、覆盖 71 个有销售 SKU，但结算仅到 11 月 1 日且币种全部缺失，因此不能确认完整月利润或认定任何 SKU 真正盈利。</p><p>已观测退款净流出 1,896.58、超龄仓储扣费 211.06（均为未确认币种的源金额），13 个 SKU 的佣金加 FBA 占销售额至少 50%，另有 16 个 SKU 的库龄分桶显示超过 180 天。</p><p>本周先核对退款与高费用 SKU、确认超龄费归属，再补齐广告、库存事件、赔付及订单证据；全部金额不含采购成本和头程，缺失金额保留未知，动作与最终结论待 Codex 对话确认。</p></header>'''
sec('优先动作清单','<p>先按已观测金额或诊断暴露额从大到小排，再列未知项；这是调查优先级，不是保证追回的金额排名。</p>'+table(['优先级','动作与责任角色','金额依据','本周验收'],[
['P1','<b>核对退款</b> · 财务 / 客服：先查 XO-MA26-NDW1、53-2X0C-IZU9、MW-BG84-978I；核验 BM-F6FL-K73E 两件退货。','1,896.58：30 天窗口已观测退款净流出；币种未知。','逐笔匹配退款、订单和退回库存；补齐销售分母。'],
['P2','<b>复核 13 个高费用 SKU</b> · 财务 / 运营：先查 8Y-5JVG-P8GN、MW-BG84-978I、S3-R2RW-I1ML 的 FBA 尺寸、重量和费率。','487.90：佣金 + FBA 高于销售额 50% 的部分；诊断暴露，不是确认超收。','核对实际账单；形成调整建议后在 Codex 确认。'],
['P3','<b>核对老库存和账单</b> · 库存 / 财务：核验 16 个超 180 天 SKU，先查 271–365 天库存 58 件和 55 件的两款。','211.06：一笔已实扣超龄费；下一月增量未知。','核对库龄分桶；取得体积、费率，比较继续持有与处置成本。'],
['P4','<b>补齐索赔证据</b> · 库存 / 索赔：取得已发布损失、找回及赔付记录，逐事件核对超过 30 天未结库存。','NEEDS_DATA：数量、估值和可索赔金额未知，不是零。','形成可审阅索赔清单；确认后才提交。']])+'<p>未启动同步、提交索赔、改价、清仓、移除库存或修改广告。</p>')
sec('四项漏损 · 月度口径排序',table(['排序','漏损项','30 天窗口金额 / 暴露额','月度结论与限制'],[
['1','退货 / 退款','<b>1,896.58</b> 源金额，币种未知','窗口内已观测净流出；完整月及未来月损失未知，不等于全部不可回收损失。'],
['2*','费用异常 / SKU 盈亏','<b>487.90</b> 诊断暴露额，币种未知','按佣金 + FBA ≥ 销售额 50% 筛查，超阈部分不是已确认多收、亏损或可节省金额。'],
['3','超龄仓储','<b>211.06</b> 源金额，币种未知','窗口内一笔实扣超龄费；下一月不处理多付金额未知。'],
['未定','丢失损坏索赔','<b>NEEDS_DATA</b>','一次性未追回余额及最近 30 天新增可索赔金额均未知。']])+'''<p class="warn">四项不能相加：费用阈值暴露不是确认损失，退款和仓储已进入部分结算贡献额；一次性索赔与持续月费不能当成同一种重复收益。结算行币种全部为 null，数值仅按源单位作暂定审阅排序，币种一致性未确认前不是可入账货币排名。</p><p>月度统一定义为 30 天。目标窗口只有 23 个日期有结算行，缺 11 月 2–8 日，不乘 30/23、不补零、不预测。实际月费需完整 30 天扣费；历史索赔余额单列，只把当期新形成且仍未结的可证实金额算新增月流量。</p>''')
sec('1 · profit-fee-analysis','''<p>销售本金 <b>42,159.15</b>；佣金 <b>6,092.01</b>；FBA 配送费 <b>11,559.57</b>；两项占销售本金 <b>41.9%</b>。销售件数只累计 Order / ItemPrice / Principal 行，为 2,211 件，费用行不重复计件。</p><p>71 个 SKU 已观测部分结算贡献额合计 <b>21,188.26</b>，扣未分配店铺费用 <b>876.68</b> 后为 <b>20,311.58</b>；税款净额 0.26 排除。币种未知，<b>不含采购成本、头程，且缺广告及未取得费用，不等于真实利润</b>。</p><p>部分贡献为负的实际 SKU 有 0 个，但真实亏损数量未知；未分配店铺费用不是一个亏损 SKU。所有完整贡献利润和真实盈亏均 NEEDS_DATA，无销售商品不填零利润。</p><h3>费用占比异常</h3>'''+table(['SKU','ASIN','销售本金','佣金 + FBA','占比','部分贡献'],[[H(x['sku']),H(mp.get(x['sku'],'未知')),M(x['sales']),M(-x['commission']-x['fba']),Q(-(x['commission']+x['fba'])/x['sales']),M(x['net']-x['tax'])] for x in high])+'''<p>50% 是透明的调查阈值，不是 Amazon 官方异常标准，未按品类 / 尺寸归一化。单件样本也保留件数供核验。广告健康为 NO_PUBLISHED_VERSION，不按销售比例造分摊；finance_get_fee_estimate / finance_get_balances 未接入，未拿试算替代实扣。</p><h3>全部 71 个有销售 SKU</h3><p>金额使用结算符号。部分贡献含下列净额、不含税；广告 / 完整利润缺失。</p><input id="search" placeholder="搜索 SKU / ASIN" aria-label="搜索 SKU 或 ASIN">'''+table(['SKU','ASIN','件数','销售本金','佣金','FBA','促销','净运费','退款净额','部分贡献','完整盈亏'],[[H(x['sku']),H(mp.get(x['sku'],'未知')),x['units'],*[M(x[k]) for k in ['sales','commission','fba','promotion','shipping','refund']],M(x['net']-x['tax']),'NEEDS_DATA'] for x in sorted(products,key=lambda x:x['net']-x['tax'])]))
sec('2 · reimbursement-recovery','''<p><b>可索赔金额未知，不是 0。</b>赔付查询返回 0 行，但同步状态 REPORT_CREATE_REJECTED、覆盖不完整；库存事件 COLLECTED_NOT_PUBLISHED / ATTRIBUTION_PENDING，不能用于认定损失。inventory_ledger_daily 查询未获支持，未绕过授权读取底层数据。</p><p>以 2026-11-09 为报告日，2026-10-10 之前事件列入超过 30 天待核范围，边界按事件时刻核对。未结数量 = 已证实丢失 / 损坏 − 已找回 − 库存赔付 − 现金赔付对应数量，按同卖家、站点、SKU / FNSKU、事件 / 索赔编号核对。</p><p>估值 = 符合资格的未结数量 × 有凭据的赔偿单价；两项均缺失。30 天是用户指定排查阈值，不证明自动取得赔偿资格；逐案有效期限待核验。未将零售售价作为赔偿单价、未提交索赔。</p>''')
sec('3 · clearance-aging-decision','''<p>只取 2026-11-08 最新报告 453621020765 的 150 行，11 月 6、7 日快照不累加；可售量合计 8,465，181–270 天分桶 186、271–365 天分桶 147，共 333 个分桶计数、涉及 16 个 SKU，不是已核实净库存。</p><p class="warn">75 / 150 行四个可见库龄桶之和与 available 不同，部分桶超过可售量；365 天以上字段未返回，部分桶为空、部分移除数为负。保留原值，不用最小值或零修饰缺失。</p>'''+table(['SKU / ASIN','可售量','181–270 天','271–365 天','分桶核对','下月增量'],[[H(x['sku'])+'<br><small>'+H(x['asin'])+'</small>',x['available'],x['a181'],x['a271'],'一致' if all(x[k] is not None for k in ['a0','a91','a181','a271']) and sum(x[k] for k in ['a0','a91','a181','a271'])==x['available'] else '需核验','NEEDS_DATA'] for x in aged])+'''<p>一笔 FBA Long Term Storage Fee 实扣 211.06（reportId 451208020758、SKU 为空），不强制分摊到上述 SKU。没有 SKU 体积、基础仓储费率和完整库龄；restock_get_clearance / restock_get_forecast 未接入，所以无法可靠估算下一月多付金额或售罄天数。</p><p>补齐后：持有月额 = 实际计费体积 × 适用月费率 + 对应库龄附加费；处置净节省 = 可避免仓储费 − 移除 / 销毁 / 清货费用与折价影响。未套公开费率或用部分结算销量当 30 天需求。</p>''')
zh={'UNWANTED_ITEM':'不再需要','APPAREL_TOO_SMALL':'尺码偏小（需核验商品适用性）','UNDELIVERABLE_UNKNOWN':'无法投递，原因未知','FOUND_BETTER_PRICE':'找到更低价格'}
sec('4 · amazon-return-weekly-analysis','''<p>最近一周 2026-11-02 至 11-08 与近 30 天均仅查到同一份报告 6 件，全部发生在 UTC 2026-11-06，涉及 5 个 SKU；全部 SELLABLE、orderMatched=false。只是已观察样本，不是完整 30 天退货量。</p><p>同期 orders 查询为 0 行，其筛选语义 sourceUpdatedAt 并非购买日期，不能当销售为零。缺可靠 SKU 发货 / 售出分母，<b>无法确定退货率最高产品</b>；BM-F6FL-K73E 样本件数最多（2 件），不能称为退货率最高。</p>'''+table(['SKU','ASIN','样本件数','原因','退货率'],[[H(k),H(next(x['asin'] for x in ret if x['sellerSku']==k)),v,'；'.join(H(zh[c])+' × '+str(n) for c,n in Counter(x['reason']['code'] for x in ret if x['sellerSku']==k).items()),'NEEDS_DATA'] for k,v in counts.most_common()])+table(['原始原因码','解释','件数','样本占比'],[[H(k),H(zh[k]),v,Q(v/6)] for k,v in reasons.most_common()])+'''<p>前周 2026-10-26 至 11-01 与前 30 天 2026-09-10 至 10-09 查询为空，但单份报告未证明周期完整覆盖，环比不可计算，不称从零增长到六。未因异常订单任意剔除退货样本。评论执行器未接入，不虚构买家原话。</p><h3>退款财务暴露 Top 8（不是退货率排名）</h3>'''+table(['SKU','退款净流出（源金额）'],[[H(x['sku']),M(-x['refund'])] for x in sorted(products,key=lambda x:x['refund'])[:8]])+'''<p>退款核算：本金 2,232.58 − 佣金返还 324.90 + 退款佣金 65.00 − 促销本金返还 67.13 + 运费退款 49.59 − 运费扣回返还 21.99 − 运费促销返还 27.60 − RestockingFee 收入 8.97 = 1,896.58，排除税款。不能将财务退款和 6 件退货硬配，也不能把可再次销售的库存价值当永久损失。</p><p>下周期三件事：客服核验“不再需要”3 件；运营核验 MW-BG84-978I 尺码原因与页面事实；物流核验 BM-F6FL-K73E 无法投递事件。更改页面、定价或广告前在 Codex 确认。</p>''')
